"""Build the public, script-free privacy site. No third-party packages required."""
from pathlib import Path
from html import escape
from urllib.parse import quote
import json

ROOT = Path(__file__).resolve().parents[1]
CONFIG = json.loads((ROOT / 'site.json').read_text(encoding='utf-8'))
PUBLIC = ROOT / 'public'
ORIGIN = CONFIG['origin']
EMAIL = CONFIG['email']
DEVELOPER = CONFIG['developer']
MAIL = 'mailto:' + EMAIL

def link(href, title):
    external = ' rel="noreferrer noopener"' if href.startswith('https://') else ''
    return f'<a href="{escape(href, quote=True)}"{external}>{title}</a>'

GOOGLE = link('https://policies.google.com/privacy', 'Google Gizlilik Politikası')
GOOGLE_EN = link('https://policies.google.com/privacy', 'Google Privacy Policy')
UNITY = link('https://unity.com/legal/game-player-and-app-user-privacy-policy', 'Unity Oyuncu ve Uygulama Kullanıcısı Gizlilik Politikası')
UNITY_EN = link('https://unity.com/legal/game-player-and-app-user-privacy-policy', 'Unity Game Player and App User Privacy Policy')
GITHUB = link('https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement', 'GitHub Gizlilik Bildirimi')
GITHUB_EN = link('https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement', 'GitHub Privacy Statement')

PRIVACY = {
'tr': [
('scope', '1. Bu politika ve geliştirici', f'<p>Bu politika, {DEVELOPER} tarafından geliştirilen <strong>Block Mirage</strong> mobil oyunu ile bu gizlilik ve destek sitesini kapsar. Gizlilik talepleriniz için {link(MAIL, EMAIL)} adresine ulaşabilirsiniz.</p><p>Güncel reklam açıklamaları Android sürümündeki Google AdMob bağlantısı için geçerlidir. Diğer platformlara farklı hizmetler eklendiğinde bu politika ve ilgili mağaza açıklamaları güncellenir.</p>'),
('local', '2. Cihazda tutulan oyun verileri', '<p>Tahta ve devam eden oyun, puanlar, kişisel rekor, macera ilerlemesi, günlük oyun sonuçları, istatistikler, görünüm tercihleri ve ses/titreşim gibi ayarlar cihazın uygulamaya ayrılmış alanında tutulur. Kayıtların bütünlüğünü ve devamlılığını sağlamak için yerel bir misafir profil kimliği ve yerel yedek dosyaları da oluşturulur.</p><p>Bu kayıtlar geliştiriciye ait bir oyun sunucusuna yüklenmez. Oyunu oynamak için kullanıcı hesabı, parola, ad veya e-posta girişi gerekmez. İşletim sistemi ayarlarınıza bağlı olarak uygulama verileri cihaz yedeğinize dahil edilebilir; bu, geliştirici tarafından işletilen bir bulut kayıt hizmeti değildir.</p>'),
('ads', '3. Reklamlar ve Google AdMob', '<p>Android sürümü ödüllü ve geçiş reklamları için Google AdMob kullanır. Reklam hizmeti; IP adresi ve bundan çıkarılabilen yaklaşık konum, reklam/cihaz ve uygun olduğunda hesapla ilişkili tanımlayıcılar, uygulama/reklam etkileşimleri ve teknik tanılama bilgilerini işleyebilir.</p><p>Bu işleme reklam sunumu ve ölçümü, hizmet analizi, güvenlik ve sahteciliğin önlenmesi amaçlarını kapsayabilir. Google reklam verilerinin aktarımında TLS kullanır. Oyunun yerel tahta kayıtlarını veya kişisel rekor dosyalarını reklam sağlayıcısına ayrıca göndermeyiz.</p><p>Kişiselleştirilmiş, kişiselleştirilmemiş veya sınırlı reklam sunumu; bölgenize, tercihlerinize ve sağlayıcının desteklediği seçeneklere bağlıdır. Ayrıntılar: '+GOOGLE+'.</p>'),
('choices', '4. Reklam ve gizlilik tercihleri', '<p>Gerekli bölgelerde Google’ın User Messaging Platform (UMP) sistemi üzerinden bir gizlilik/izin mesajı sunulur. Reklam istekleri, bu sistemin izin durumuna göre başlatılır.</p><p>Gerekli olduğunda oyunda <strong>Ayarlar → Diğer ayarlar → Reklam gizliliği</strong> seçeneği görünür. Buradan tercihlerinizi yeniden açabilirsiniz. Bir tercihi değiştirmek önceki hukuka uygun işlemleri geri almaz; mevcut reklam seçeneklerini etkiler. Kişiselleştirmeyi reddetmek her durumda tüm reklamların kaldırıldığı anlamına gelmez.</p><p>Android’in reklam gizliliği ayarlarından reklam kimliğinizi yönetebilirsiniz. Google hesabı seçenekleri için '+link('https://myadcenter.google.com/', 'Google Reklam Merkezim')+' kullanılabilir.</p>'),
('engine', '5. Unity ve teknik çalışma bilgileri', '<p>Oyun Unity motoruyla çalışır. Motorun sürüme ve platforma bağlı temel kullanım/teknik işlevleri; cihaz, işletim sistemi, uygulama sürümü ve çalışma performansı gibi teknik bilgileri işleyebilir. Ayrı bir geliştirici oyun hesabı veya çevrimiçi oyuncu analiz sistemi işletmiyoruz; mevcut yapılandırmada ayrı Unity Analytics oyun olayı takibi ve Unity Cloud Diagnostics raporlaması etkinleştirilmemiştir.</p><p>Unity teknolojilerinin kendi veri uygulamaları için '+UNITY+' incelenebilir.</p>'),
('sharing', '6. Skor görselleri ve sizin başlattığınız paylaşım', '<p>Skor görseli oluşturduğunuzda görsel cihazda hazırlanır. Görsel; puan, oyun modu ve ilgili oyun sonuçlarını içerebilir. Yalnızca paylaşımı seçerseniz işletim sisteminin paylaşım penceresi üzerinden seçtiğiniz uygulamaya iletilir. Otomatik bir sosyal ağ yüklemesi yapılmaz.</p><p>Başka bir uygulamaya gönderdiğiniz kopyalar o uygulamanın gizlilik ve saklama kurallarına tabidir.</p>'),
('contact', '7. Destek yazışmaları', '<p>Bize e-posta gönderirseniz e-posta adresiniz, mesaj içeriğiniz ve kendi isteğinizle eklediğiniz cihaz bilgisi veya ekran görüntüleri talebinizi yanıtlamak için işlenir. Destek kanalı Gmail üzerinden sağlanır; e-posta hizmetinin veri işlemesi Google’ın politikalarına tabidir.</p><p>Lütfen parola, banka/kart bilgisi, kimlik belgesi veya gereksiz kişisel veri göndermeyin. Ekran görüntülerinde başka kişilere ait bilgileri kapatın.</p>'),
('purposes', '8. İşleme amaçları ve dayanaklar', '<p>Yerel kayıtlar oyunu sunmak ve ilerlemenizi korumak için; destek verileri talebinize yanıt vermek için; sınırlı teknik bilgiler hizmetin güvenli ve kararlı çalışması için kullanılır. Reklam verilerinin amaçları yukarıda açıklanmıştır.</p><p>İşlemeye göre, talep ettiğiniz hizmetin sağlanması, güvenlik ve destek için gerekli meşru menfaatler, hukuki yükümlülükler ve gerektiğinde rıza gibi uygulanabilir hukuki dayanaklar söz konusu olabilir. Rızaya bağlı işleme için ilgili tercih araçlarını kullanarak rızanızı geri alabilirsiniz.</p>'),
('providers', '9. Sağlayıcılar ve uluslararası işleme', '<p>Google (AdMob, UMP ve destek e-postası), Unity (oyun motoru/teknik hizmetler) ve GitHub (bu sitenin barındırılması) açıklanan işlevleri sağlar. Bu sağlayıcılar verileri bulunduğunuz ülke dışındaki altyapılarda işleyebilir; kendi işleme koşulları, saklama uygulamaları ve uygulanabilir aktarım korumaları kendi politikalarında açıklanır.</p><p>Yerel oyun kayıtlarını reklamverenlere satmayız. Reklam sağlayıcısının yukarıda açıklanan veri işleme ve paylaşımı bu ifadeden ayrı değerlendirilmelidir. Gerekli hukuki yükümlülükler veya hakların korunması kapsamında sınırlı açıklamalar yapılabilir.</p>'),
('retention', '10. Saklama ve silme', '<p>Yerel oyun verileri, uygulama verilerini temizleyene veya uygulamayı kaldırana kadar cihazda tutulabilir. Cihaz/işletim sistemi yedekleri ve dışarı paylaştığınız dosyalar ayrıca yönetilir. Destek yazışmaları yalnızca talebin ele alınması, gerekli takip ve uygulanabilir hukuki saklama ihtiyaçları devam ettiği sürece tutulur; artık gerekli olmadığında silinir veya kimlikle ilişkilendirilemeyecek hâle getirilir.</p><p>Reklam ve barındırma sağlayıcılarının kendi kayıtları kendi saklama politikalarına tabidir. Uygulama verilerini silmek bu kayıtları otomatik olarak silmez. Adım adım açıklama için '+link('/block-mirage/data-deletion/', 'veri silme ve tercih yönetimi sayfasını')+' inceleyin.</p>'),
('security', '11. Güvenlik', '<p>Yerel dosyalar uygulamanın ayrılmış depolama alanında ve işletim sisteminin erişim kontrolleri altında tutulur. Site HTTPS üzerinden sunulur. Üçüncü taraf hizmetlerin kendi güvenlik önlemleri bulunur. Hiçbir cihaz, saklama veya aktarım yöntemi için mutlak güvenlik garantisi verilemez.</p>'),
('children', '12. Çocukların gizliliği', '<p>Block Mirage çocuklara özel bir uygulama olarak tasarlanmamıştır. Çocuklardan bilerek ad, okul, adres veya iletişim bilgisi istemeyiz. Bir ebeveyn/vasinin bir çocukla ilgili kişisel bilginin bize gönderildiğini düşünmesi hâlinde iletişim adresimizden başvurmasını rica ederiz; uygulanabilir yükümlülüklere göre inceleme ve gerekli silme işlemleri yapılır.</p><p>Mağazadaki hedef yaş grubu ve içerik derecelendirmesi ayrıca dikkate alınmalıdır.</p>'),
('website', '13. Bu web sitesi', '<p>Bu siteye reklam, ziyaretçi analiz aracı, harici yazı tipi veya izleme çerezi yerleştirmiyoruz. Sitede bir veri toplama formu veya kullanıcı girişi bulunmaz; e-posta bağlantısı kendi e-posta uygulamanızı açar.</p><p>Site GitHub Pages üzerinde barındırılır. GitHub, siteyi sunarken IP adresi gibi bağlantı bilgilerini güvenlik ve hizmet işletimi için kendi politikası doğrultusunda işleyebilir. Ayrıntılar: '+GITHUB+'.</p>'),
('rights', '14. Haklarınız ve iletişim', f'<p>Bulunduğunuz yere ve uygulanabilir hukuka bağlı olarak verileriniz hakkında bilgi/erişim, düzeltme, silme, işlemeyi sınırlama, itiraz, taşınabilirlik ve rızayı geri alma haklarınız bulunabilir. Yetkili veri koruma makamına başvurma hakkınız da olabilir.</p><p>Geliştiricinin kontrolündeki verilerle ilgili talepleri {link(MAIL+"?subject=Block%20Mirage%20-%20Gizlilik%20talebi", EMAIL)} adresine iletebilirsiniz. Cihazınızda kalan kayıtlar için aşağıdaki silme adımlarını; doğrudan Google/Unity/GitHub tarafından işlenen veriler için ilgili sağlayıcının araçlarını da kullanmanız gerekebilir.</p><p>Önemli bir veri uygulaması değişikliğinde bu sayfayı ve güncelleme tarihini yenileriz; gerekiyorsa uygulama içinde ek bilgilendirme veya izin sunulur.</p>'),
],
'en': [
('scope', '1. About this policy and the developer', f'<p>This policy covers <strong>Block Mirage</strong>, a mobile game developed by {DEVELOPER}, and this privacy and support website. For privacy enquiries, contact {link(MAIL, EMAIL)}.</p><p>The advertising descriptions currently apply to Google AdMob in the Android version. If different services are added on other platforms, this policy and the relevant store disclosures will be updated.</p>'),
('local', '2. Game data stored on your device', '<p>The board and saved run, scores, personal best, adventure progress, daily results, statistics, appearance preferences and settings such as sound and haptics are kept in app-specific device storage. A local guest profile identifier and local backup files support save integrity and continuity.</p><p>These records are not uploaded to a developer-operated game server. Playing does not require an account, password, name or email address. Depending on your operating-system settings, app data may be included in device backups; this is not a developer-operated cloud-save service.</p>'),
('ads', '3. Advertising and Google AdMob', '<p>The Android version uses Google AdMob for rewarded and interstitial ads. The advertising service may process an IP address and inferred general location, advertising/device and applicable account-related identifiers, app/ad interactions, and technical diagnostic information.</p><p>Purposes may include ad delivery and measurement, service analytics, security and fraud prevention. Google uses TLS for advertising-data transmission. We do not separately send local board saves or personal-best files to the advertising provider.</p><p>Personalized, non-personalized or limited ads depend on your region, choices and the provider’s supported options. See the '+GOOGLE_EN+'.</p>'),
('choices', '4. Advertising and privacy choices', '<p>Where required, Google’s User Messaging Platform (UMP) presents a privacy/consent message. Ad requests start according to the permission status reported by that system.</p><p>When required, the game displays <strong>Settings → Other settings → Ad privacy</strong> (currently labelled “Ayarlar → Diğer ayarlar → Reklam gizliliği” in Turkish). You can reopen your choices there. Changes affect current advertising options and do not reverse prior lawful processing. Rejecting personalization does not necessarily remove all ads.</p><p>You can manage your advertising identifier in Android’s ad-privacy settings. Google account options are also available through '+link('https://myadcenter.google.com/', 'My Ad Center')+'.</p>'),
('engine', '5. Unity and technical operation', '<p>The game runs on the Unity engine. Basic technical/usage features, depending on the engine version and platform, may process device, operating-system, app-version and runtime-performance information. We do not operate a separate cloud player account or online player-analytics system; separate Unity Analytics gameplay-event tracking and Unity Cloud Diagnostics reporting are not enabled in the current configuration.</p><p>For Unity’s own technology practices, see the '+UNITY_EN+'.</p>'),
('sharing', '6. Score images and sharing you initiate', '<p>A score image is generated on your device when you request one. It may contain your score, game mode and related game results. Only if you choose to share it is it passed to the app you select through the operating-system share sheet. The game does not automatically upload it to a social network.</p><p>Copies you send elsewhere are subject to the receiving app’s privacy and retention practices.</p>'),
('contact', '7. Support correspondence', '<p>If you email us, your email address, message and any device details or screenshots you voluntarily attach are processed to respond to your request. Support email uses Gmail; Google’s policies apply to the email service’s processing.</p><p>Please do not send passwords, banking/card information, identity documents or unnecessary personal data. Redact information about other people from screenshots.</p>'),
('purposes', '8. Purposes and legal grounds', '<p>Local records provide the game and preserve progress; support data is used to respond to your request; limited technical information supports secure and reliable operation. Advertising purposes are described above.</p><p>Depending on the processing, applicable grounds may include providing the service you request, legitimate interests in security and support, legal obligations, and consent where required. You can withdraw consent-based choices using the relevant preference tools.</p>'),
('providers', '9. Providers and international processing', '<p>Google (AdMob, UMP and support email), Unity (engine/technical services), and GitHub (website hosting) provide the functions described here. Their infrastructure may process data outside your country; their policies describe their processing terms, retention practices and applicable transfer safeguards.</p><p>We do not sell local game saves to advertisers. The advertising provider’s processing and sharing described above must be considered separately from that statement. Limited disclosure may also occur for applicable legal obligations or protection of rights.</p>'),
('retention', '10. Retention and deletion', '<p>Local game data may remain on your device until you clear app data or uninstall the app. Device/operating-system backups and externally shared files are managed separately. Support correspondence is retained only while needed to handle the request, necessary follow-up and applicable legal retention needs; it is then deleted or made no longer identifiable.</p><p>Advertising and hosting providers retain their own records under their policies. Clearing app data does not automatically erase those records. See the '+link('/block-mirage/data-deletion/en/', 'data deletion and choices guide')+' for practical steps.</p>'),
('security', '11. Security', '<p>Local files are kept in app-specific storage subject to operating-system access controls. This website uses HTTPS. Third-party services have their own security measures. No device, storage or transmission method can be guaranteed absolutely secure.</p>'),
('children', '12. Children’s privacy', '<p>Block Mirage is not designed as a child-specific application. We do not knowingly ask children for names, school details, addresses or contact information. A parent or guardian who believes a child’s personal information has been sent to us can contact us for review and any deletion required by applicable obligations.</p><p>The target audience and content rating displayed in the store should also be considered.</p>'),
('website', '13. This website', '<p>We do not place ads, visitor-analytics tools, external fonts or tracking cookies on this website. It has no data-submission form or user login; email links open your own email application.</p><p>The site is hosted on GitHub Pages. GitHub may process connection information, including IP addresses, for security and service operation under its own policy. See the '+GITHUB_EN+'.</p>'),
('rights', '14. Your rights and contact', f'<p>Depending on your location and applicable law, you may have rights to information/access, correction, deletion, restriction, objection, portability and withdrawal of consent. You may also have a right to contact the competent data-protection authority.</p><p>Send requests about data controlled by the developer to {link(MAIL+"?subject=Block%20Mirage%20-%20Privacy%20request", EMAIL)}. For records that remain on your device, follow the deletion guide; for data processed directly by Google, Unity or GitHub, you may also need to use that provider’s tools.</p><p>Material changes to data practices will be reflected on this page with an updated date and, where required, additional in-app information or consent.</p>'),
]}

