DELETION = {
'tr': [
('account', 'Oyun hesabı gerekmiyor', '<p>Block Mirage’da geliştiriciye ait bir çevrimiçi hesap oluşturulmaz. Bu nedenle kapatılacak bir oyun hesabı veya sunucumuzda silinecek bir bulut kayıt profili bulunmaz. Yerel kayıtlar, reklam sağlayıcısının verileri ve destek e-postaları farklı yerlerde tutulur.</p>'),
('android', '1. Android cihazındaki oyun verilerini temizleyin', '<ol><li>Telefonun <strong>Ayarlar</strong> uygulamasını açın.</li><li><strong>Uygulamalar → Block Mirage → Depolama</strong> bölümüne gidin.</li><li><strong>Verileri temizle / Depolamayı temizle</strong> seçeneğini kullanın. Menü adları cihaza göre değişebilir.</li></ol><p><strong>Bu işlem ilerleme, rekor, kaydedilmiş oyun ve tercihleri kalıcı olarak kaldırabilir.</strong> İşlem geri alınamaz. Uygulamayı kaldırmak da uygulamaya ait yerel verileri normal olarak kaldırır; işletim sistemi yedekleri tekrar yüklemede verileri geri getirebilir.</p>'),
('backups', '2. Yedekleri ve paylaşılan görselleri ayrıca yönetin', '<p>Cihazınızın bulut yedekleme ayarlarını kontrol edin. Daha önce galeriye veya başka bir uygulamaya kaydettiğiniz/paylaştığınız skor görsellerini ilgili konumdan ayrıca silin. Alıcıların veya paylaşım servislerinin kopyalarını uygulama verilerini temizlemek tek başına silmez.</p>'),
('ads', '3. Reklam tercihlerini değiştirin', '<p>Gerekli olduğunda <strong>Ayarlar → Diğer ayarlar → Reklam gizliliği</strong> yoluyla izin seçeneklerini yeniden açabilirsiniz. Android’in reklam gizliliği ayarları ve '+link('https://myadcenter.google.com/', 'Google Reklam Merkezim')+' de kullanılabilir.</p><p>Bu seçenekler üçüncü tarafın tüm geçmiş kayıtlarının otomatik olarak silineceği anlamına gelmez. Google veya Unity tarafından tutulan kayıtlar için ilgili sağlayıcının gizlilik araçlarını kullanmanız gerekebilir.</p>'),
('request', '4. Geliştiriciye veri talebi gönderin', f'<p>Destek yazışması veya geliştiricinin kontrolündeki başka bir veri hakkında talepte bulunmak için {link(MAIL+"?subject=Block%20Mirage%20-%20Veri%20silme%20talebi", EMAIL)} adresine yazın. Hangi talebinizle ilgili olduğunu ve ne istediğinizi açıklayın. Gereksiz hassas belge eklemeyin.</p><p>Cihazınızdaki kayıtlara uzaktan erişemediğimiz için bunları e-posta yoluyla sizin yerinize silemeyiz. Uygulanabilir saklama yükümlülükleri olan kayıtlar gerekçesiyle sınırlı süre tutulabilir; talebiniz uygun kapsamda değerlendirilir.</p>'),
],
'en': [
('account', 'No game account is required', '<p>Block Mirage does not create a developer-operated online account. There is no game account to close or cloud-save profile on our server to delete. Local saves, advertising-provider data and support emails are stored separately.</p>'),
('android', '1. Clear Android game data', '<ol><li>Open your phone’s <strong>Settings</strong> app.</li><li>Go to <strong>Apps → Block Mirage → Storage</strong>.</li><li>Choose <strong>Clear data / Clear storage</strong>. Names vary by device.</li></ol><p><strong>This can permanently remove progress, personal bests, saved games and preferences.</strong> It cannot be undone. Uninstalling normally removes local app data too, but an operating-system backup may restore it on reinstallation.</p>'),
('backups', '2. Manage backups and shared images separately', '<p>Check your device’s cloud-backup settings. Delete score images you saved or shared from their respective locations. Clearing app data alone does not delete copies held by recipients or sharing services.</p>'),
('ads', '3. Change advertising choices', '<p>When required, reopen preferences through <strong>Settings → Other settings → Ad privacy</strong> (Turkish: “Ayarlar → Diğer ayarlar → Reklam gizliliği”). You can also use Android’s ad-privacy settings and '+link('https://myadcenter.google.com/', 'My Ad Center')+'.</p><p>These controls do not mean that all historical third-party records are automatically deleted. You may need to use the relevant provider’s privacy tools for records held by Google or Unity.</p>'),
('request', '4. Send a request to the developer', f'<p>For support correspondence or other data controlled by the developer, email {link(MAIL+"?subject=Block%20Mirage%20-%20Data%20deletion%20request", EMAIL)}. Explain which interaction your request concerns and what you would like us to do. Do not attach unnecessary sensitive documents.</p><p>We cannot remotely access or erase saves that remain on your device. Records subject to applicable retention obligations may be kept for a limited period for that reason; requests are assessed within the appropriate scope.</p>'),
]}

def route(kind, lang='tr'):
    return '/block-mirage/' + kind + ('/en/' if lang == 'en' else '/')

def shell(title, description, body, path='/', lang='tr', alternate=None, current='home'):
    english=lang=='en'
    nav=[('privacy','Privacy' if english else 'Gizlilik'),('support','Support' if english else 'Destek'),('data-deletion','Your data' if english else 'Verilerin')]
    nav_html=''.join(f'<a href="{route(k,lang)}"'+(' aria-current="page"' if current==k else '')+f'>{v}</a>' for k,v in nav)
    alternate_tag=f'<link rel="alternate" hreflang="{"tr" if english else "en"}" href="{ORIGIN}{alternate}">' if alternate else ''
    language=f'<a class="language" href="{alternate}" lang="{"tr" if english else "en"}">{"Türkçe" if english else "English"}</a>' if alternate else '<a class="language" href="/block-mirage/privacy/en/" lang="en">English</a>'
    return f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{escape(title)} · Block Mirage</title><meta name="description" content="{escape(description,quote=True)}">
<meta name="theme-color" content="#141e35"><meta name="referrer" content="no-referrer">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'self'; img-src 'self'; font-src 'self'; base-uri 'self'; form-action 'none'">
<link rel="canonical" href="{ORIGIN}{path}">{alternate_tag}<link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/styles.css">
<meta property="og:title" content="{escape(title,quote=True)} · Block Mirage"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{ORIGIN}{path}"></head>
<body><a class="skip" href="#content">{"Skip to content" if english else "İçeriğe geç"}</a>
<header class="site-header"><a class="brand" href="/" aria-label="Block Mirage — {'Home' if english else 'Ana sayfa'}"><span class="brandmark" aria-hidden="true"><i></i><i></i><i></i></span><span><b>Block Mirage</b><small>{DEVELOPER}</small></span></a><nav aria-label="{'Main navigation' if english else 'Ana gezinme'}">{nav_html}{language}</nav></header>
<main id="content" tabindex="-1">{body}</main>
<footer class="site-footer"><div><b>Block Mirage</b><span>{'Privacy, clearly explained.' if english else 'Gizlilik, açıkça anlatılmış.'}</span></div><div>{link(MAIL,EMAIL)}<small>© 2026 {DEVELOPER}</small></div></footer></body></html>'''

def document(kind, lang, title, lead, sections):
    toc=''.join(f'<a href="#{key}">{escape(heading)}</a>' for key,heading,_ in sections)
    content=''.join(f'<section id="{key}"><h2>{escape(heading)}</h2>{html}</section>' for key,heading,html in sections)
    date='27 October 2026' if lang=='en' else '27 Ekim 2026'
    body=f'''<div class="document-heading"><p class="eyebrow">Block Mirage / {DEVELOPER}</p><h1>{title}</h1><p class="lead">{lead}</p><p class="date">{'Last updated' if lang=='en' else 'Son güncelleme'}: <time datetime="2026-10-27">{date}</time></p></div>
<div class="document-grid"><aside class="toc" aria-label="{'On this page' if lang=='en' else 'Bu sayfada'}"><strong>{'On this page' if lang=='en' else 'Bu sayfada'}</strong>{toc}</aside><article class="document">{content}<div class="contact-note"><span>{'Need help?' if lang=='en' else 'Sorun mu var?'}</span>{link(MAIL,EMAIL)}</div></article></div>'''
    alternate=route(kind,'tr' if lang=='en' else 'en')
    return shell(title,lead,body,route(kind,lang),lang,alternate,kind)

def write(path,text):
    target=PUBLIC/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(text,encoding='utf-8',newline='\n')

HOME='''<section class="hero"><div><p class="eyebrow">KARAGOZPASHA STUDIO / OYUNCU BİLGİ MERKEZİ</p><h1>Oyuna odaklan.<br><em>Bilgilerin açık olsun.</em></h1><p class="lead">Block Mirage’ın gizlilik uygulamaları, veri tercihleri ve destek kanalı. Aradığın bilgi, tek bir yerde.</p><div class="hero-actions"><a class="button primary" href="/block-mirage/privacy/">Gizlilik politikasını oku <span aria-hidden="true">↗</span></a><a class="button secondary" href="/block-mirage/support/">Destek al</a></div><div class="facts"><span>Hesap oluşturmak gerekmez</span><span>Oyun kayıtları cihazında</span></div></div><div class="block-art" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><div>BLOCK<br><b>MIRAGE</b></div></div></section>
<section class="home-cards" aria-label="Gizlilik ve destek sayfaları"><a class="info-card" href="/block-mirage/privacy/"><span class="number">01 / GİZLİLİK</span><h2>Ne, neden işlenir?</h2><p>Yerel oyun verileri, reklam hizmetleri, izinler ve saklama açıklamaları.</p><span class="card-action">Politikayı incele <span aria-hidden="true">↗</span></span></a><a class="info-card" href="/block-mirage/data-deletion/"><span class="number">02 / VERİ KONTROLÜ</span><h2>Tercihlerin sende.</h2><p>Cihazdaki kayıtları silme, reklam tercihlerini değiştirme ve veri talepleri.</p><span class="card-action">Adımları gör <span aria-hidden="true">↗</span></span></a><a class="info-card" href="/block-mirage/support/"><span class="number">03 / DESTEK</span><h2>Birlikte çözelim.</h2><p>Bir sorun mu yaşadın? Destek veya gizlilik talebini doğrudan bize ilet.</p><span class="card-action">İletişime geç <span aria-hidden="true">↗</span></span></a></section>
<section class="plain-note"><span class="status-dot" aria-hidden="true"></span><p><strong>Oyun verisi ile reklam verisi aynı şey değildir.</strong> İlerlemen cihazında tutulur. Reklam sağlayıcıları, reklamları sunmak ve ölçmek için ayrı veriler işleyebilir. Ayrıntılar gizlilik politikasında açıklanır.</p></section>'''

def build():
    write('index.html',shell('Gizlilik ve destek','Block Mirage gizlilik politikası, veri tercihleri ve destek bağlantıları.',HOME))
    write('block-mirage/index.html',shell('Gizlilik ve destek','Block Mirage gizlilik politikası, veri tercihleri ve destek bağlantıları.',HOME,'/block-mirage/'))
    for lang in ('tr','en'):
        choices=[('privacy','Privacy policy' if lang=='en' else 'Gizlilik politikası','How the game and its service providers handle information.' if lang=='en' else 'Oyun ve hizmet sağlayıcılarının bilgileri nasıl işlediğine dair açıklamalar.',PRIVACY[lang]),('support','Support' if lang=='en' else 'Destek','Contact the developer about gameplay, ads or privacy.' if lang=='en' else 'Oynanış, reklamlar veya gizlilik konularında geliştiriciye ulaşın.',SUPPORT[lang]),('data-deletion','Data deletion and choices' if lang=='en' else 'Veri silme ve tercihler','Manage local saves, advertising choices and support requests.' if lang=='en' else 'Yerel kayıtları, reklam tercihlerini ve veri taleplerini yönetin.',DELETION[lang])]
        for kind,title,lead,sections in choices:write(route(kind,lang).lstrip('/')+'index.html',document(kind,lang,title,lead,sections))
    write('app-ads.txt',f"google.com, {CONFIG['publisher']}, DIRECT, f08c47fec0942fa0\n")
    paths=['/','/block-mirage/']+[route(kind,lang) for kind in ('privacy','support','data-deletion') for lang in ('tr','en')]
    write('sitemap.xml','<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN}{p}</loc><lastmod>{CONFIG["updated"]}</lastmod></url>' for p in paths)+'</urlset>\n')
    write('robots.txt',f'User-agent: *\nAllow: /\nSitemap: {ORIGIN}/sitemap.xml\n')
    write('.nojekyll','')
    write('404.html',shell('Sayfa bulunamadı','Aradığınız sayfa bulunamadı.','<section class="document-heading"><p class="eyebrow">404</p><h1>Bu sayfa burada değil.</h1><p class="lead">Gizlilik ve destek merkezine dönebilirsin.</p><a class="button primary" href="/">Ana sayfaya dön</a></section>','/404.html'))
    print('Built',len(list(PUBLIC.rglob('*.html'))),'HTML pages in',PUBLIC)

if __name__=='__main__':build()
